DDAbf/r8+fz5/Pn8+fz5/Pn8+fz5/Pn8+fz5/Pn8+fz5/Pn8+fz5/Pn8+W/7+f8BL1MR6gBwDQA=
PAYLOAD_EOF
[ -f src/graph_dashboard/package.xml ] || die "extraction failed (src/graph_dashboard/package.xml missing)"
say "extracted $(find src/graph_dashboard -type f | wc -l) files"

# ------------------------------------------------------------------- build
# Build ONLY this package: a bare catkin_make builds every package in the
# workspace, so dropping the installer into an existing workspace would
# rebuild (and could fail on) unrelated packages. --only-pkg-with-deps is
# catkin's equivalent of colcon's --packages-select; it writes
# CATKIN_WHITELIST_PACKAGES into the CMake cache, which is cleared right
# after so a later plain catkin_make here still builds everything.
say "building (catkin_make --only-pkg-with-deps graph_dashboard) ..."
catkin_make --only-pkg-with-deps graph_dashboard
WHITELIST_CLEARED=1
cmake -DCATKIN_WHITELIST_PACKAGES="" build >/dev/null 2>&1 || WHITELIST_CLEARED=0
if [ "$WHITELIST_CLEARED" -eq 0 ]; then
  say "note: could not clear CATKIN_WHITELIST_PACKAGES automatically — if a later"
  say "      plain 'catkin_make' here builds only graph_dashboard, run:"
  say "      catkin_make -DCATKIN_WHITELIST_PACKAGES=''"
fi

# ------------------------------------------------------------- self-verify
set +u
# shellcheck disable=SC1091
source devel/setup.bash
set -u
say "running the package self-test (ephemeral port, safe next to a running dashboard) ..."
if rosrun graph_dashboard bench_test --src src; then
  say "self-test passed"
else
  die "self-test FAILED — see the check list above"
fi

# ------------------------------------------------------------------- usage
cat <<'USAGE'

graph_dashboard installed. From this directory:

  source devel/setup.bash
  rosrun graph_dashboard scan          # write graph.json + summary
  rosrun graph_dashboard serve         # dashboard: http://127.0.0.1:8092/
  rosrun graph_dashboard bench_test    # re-run the self-test any time

Deep links for your team:  /?focus=<node-or-topic>  opens the focus panel,
/?hide=<pkg1,pkg2,tests>  hides packages/test harnesses, ?highlight=<name>
lights a full chain. Full docs: src/graph_dashboard/README.md
USAGE
